int distance(int A[], int n) {
    int dp[n];
    int i, j, maxLen = 0;

    for (i = 0; i < n; i++) {
        dp[i] = 1;
        for (j = 0; j < i; j++) {
            if (A[j] <= A[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > maxLen)
            maxLen = dp[i];
    }

    return n - maxLen;
}

